#!/usr/bin/env bash
# recipes/crate-fallible-streaming-iterator--0-1-9/build.sh -- stage the fallible-streaming-iterator 0.1.9 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/fallible-streaming-iterator-0.1.9"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
# cargo reads a directory-source entry's checksums from here. "package" is the
# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"7360491ce676a36bf9bb3c56c1aa791658183a54d2744120f27285738d90465a"}\n' > "${dest}/.cargo-checksum.json"
